    insert into public.quizzes (pin, title, is_sample)
    insert into public.questions (quiz_id, position, topic, level, q, choices, answer, explain) values
    (qid, 0, 'วิทยาศาสตร์', 1, 'โลกมีการเคลื่อนที่แบบใดรอบดวงอาทิตย์?', '["การหมุนรอบตัวเอง","การโคจรรอบดวงอาทิตย์","การสั่นสะเทือน","การเคลื่อนที่เป็นเส้นตรง"]'::jsonb, 1, 'การโคจรคือการเคลื่อนที่รอบดวงอาทิตย์ ใช้เวลาประมาณ 365.25 วัน ส่วนการหมุนรอบตัวเองทำให้เกิดกลางวันและกลางคืน'),
    (qid, 1, 'วิทยาศาสตร์', 2, 'ข้อใดเป็นสาเหตุหลักที่ทำให้เกิดฤดูกาลบนโลก?', '["ระยะห่างจากดวงอาทิตย์เปลี่ยนไป","แกนโลกเอียงประมาณ 23.5 องศา","ดวงจันทร์บังแสงอาทิตย์","โลกหมุนเร็วขึ้นในบางช่วง"]'::jsonb, 1, 'แกนโลกที่เอียงทำให้แต่ละซีกโลกรับแสงอาทิตย์ในมุมและระยะเวลาต่างกันตลอดปี จึงเกิดฤดูกาล'),
    (qid, 2, 'วิทยาศาสตร์', 3, 'วัตถุมวล 2 kg ถูกแรงลัพธ์ 10 N กระทำ จะมีความเร่งเท่าใด?', '["0.2 m/s²","5 m/s²","12 m/s²","20 m/s²"]'::jsonb, 1, 'ใช้กฎข้อที่ 2 ของนิวตัน a = F/m = 10/2 = 5 m/s²'),
    (qid, 3, 'คณิตศาสตร์', 1, 'ถ้า 3x + 5 = 20 แล้ว x เท่ากับเท่าใด?', '["3","5","7","15"]'::jsonb, 1, 'ย้าย 5 ไปอีกฝั่งได้ 3x = 15 แล้วหารด้วย 3 ได้ x = 5'),
    (qid, 4, 'คณิตศาสตร์', 2, 'ค่าของ (-2)³ + 4² คือเท่าใด?', '["8","-24","24","0"]'::jsonb, 0, '(-2)³ = -8 และ 4² = 16 รวมกันได้ -8 + 16 = 8'),
    (qid, 5, 'คณิตศาสตร์', 3, 'สามเหลี่ยมมุมฉากมีด้านประกอบมุมฉากยาว 6 และ 8 หน่วย ด้านตรงข้ามมุมฉากยาวเท่าใด?', '["10 หน่วย","12 หน่วย","14 หน่วย","48 หน่วย"]'::jsonb, 0, 'ใช้ทฤษฎีบทพีทาโกรัส c² = 6² + 8² = 36 + 64 = 100 ดังนั้น c = 10'),
    (qid, 6, 'ภาษาอังกฤษ', 1, 'Choose the correct word: She ___ to school every day.', '["go","goes","going","gone"]'::jsonb, 1, 'ประธานเอกพจน์บุรุษที่ 3 (She) ใน Present Simple ต้องเติม -es ที่กริยา จึงเป็น goes'),
    (qid, 7, 'ภาษาอังกฤษ', 2, 'Which sentence is in the past perfect tense?', '["I have eaten.","I had eaten before he came.","I am eating.","I will eat."]'::jsonb, 1, 'Past Perfect ใช้ had + V3 เพื่อบอกเหตุการณ์ที่เกิดก่อนอีกเหตุการณ์หนึ่งในอดีต'),
    (qid, 8, 'ภาษาอังกฤษ', 3, 'คำว่า "reluctant" มีความหมายใกล้เคียงกับคำใด?', '["eager","unwilling","happy","careful"]'::jsonb, 1, 'reluctant แปลว่า ไม่เต็มใจ ซึ่งตรงกับ unwilling ส่วน eager มีความหมายตรงข้าม'),
    (qid, 9, 'ภาษาไทย', 1, 'คำใดสะกดถูกต้อง?', '["อนุญาติ","อนุญาต","อนุญาด","อนุยาต"]'::jsonb, 1, 'คำที่ถูกต้องคือ อนุญาต (ไม่มีสระอิ) เป็นคำที่มักสะกดผิดบ่อย'),
    (qid, 10, 'ภาษาไทย', 2, 'สำนวน "น้ำขึ้นให้รีบตัก" มีความหมายตรงกับข้อใด?', '["ควรขยันตักน้ำเก็บไว้","เมื่อมีโอกาสควรรีบทำ","ไม่ควรประมาทในชีวิต","ทำงานให้ทันเวลาน้ำขึ้น"]'::jsonb, 1, 'สำนวนนี้หมายถึง เมื่อมีโอกาสดีเข้ามา ควรรีบคว้าไว้ก่อนโอกาสจะหมดไป'),
    (qid, 11, 'ภาษาไทย', 3, 'ข้อใดใช้โวหารภาพพจน์ประเภทอุปมา?', '["เธอสวยดั่งดอกไม้แรกแย้ม","ลมกระซิบข้างหู","ฟ้าร้องไห้ทั้งคืน","เสียงดังเปรี้ยงปร้าง"]'::jsonb, 0, 'อุปมาคือการเปรียบเทียบโดยใช้คำเชื่อม เช่น ดั่ง เหมือน ราวกับ ส่วน "ลมกระซิบ" และ "ฟ้าร้องไห้" เป็นบุคคลวัต'),
    (qid, 12, 'สังคมศึกษา', 1, 'ประเทศไทยมีการปกครองระบอบใด?', '["สมบูรณาญาสิทธิราชย์","ประชาธิปไตยอันมีพระมหากษัตริย์ทรงเป็นประมุข","สังคมนิยม","สาธารณรัฐ"]'::jsonb, 1, 'ประเทศไทยปกครองระบอบประชาธิปไตยอันมีพระมหากษัตริย์ทรงเป็นประมุข ตั้งแต่ปี พ.ศ. 2475'),
    (qid, 13, 'สังคมศึกษา', 2, 'ข้อใดเป็นทรัพยากรที่ใช้แล้วหมดไป?', '["แสงอาทิตย์","ลม","น้ำมันดิบ","ป่าไม้ที่ปลูกทดแทน"]'::jsonb, 2, 'น้ำมันดิบเกิดจากซากสิ่งมีชีวิตใช้เวลานับล้านปี เมื่อใช้แล้วไม่สามารถสร้างทดแทนได้ในเวลาอันสั้น'),
    (qid, 14, 'สังคมศึกษา', 3, 'ถ้าความต้องการซื้อสินค้าเพิ่มขึ้น ขณะที่ปริมาณสินค้าคงเดิม ราคาสินค้ามักเป็นอย่างไร?', '["ลดลง","สูงขึ้น","คงที่","เป็นศูนย์"]'::jsonb, 1, 'ตามกฎอุปสงค์และอุปทาน เมื่ออุปสงค์เพิ่มแต่อุปทานคงที่ ราคาดุลยภาพจะสูงขึ้น');
